package com.zhibrary.book;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/books") @CrossOrigin(origins="http://localhost:5173") public class BookController { private final BookService service; public BookController(BookService service){this.service=service;} @GetMapping public List<Book> list(@RequestParam(required=false)String query){return service.search(query);} @PostMapping public ResponseEntity<Book> add(@RequestBody Book b){return ResponseEntity.ok(service.add(b));} @PutMapping("/{id}") public Book update(@PathVariable Long id,@RequestBody Book b){return service.update(id,b);} @PatchMapping("/{id}/status") public Book status(@PathVariable Long id,@RequestParam BookStatus value){return service.setStatus(id,value);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();} }
